```python
import errno
import os

pipes = []

try:
    while True:
        try:
            read_fd, write_fd = os.pipe()
            pipes.append((read_fd, write_fd))

            if len(pipes) % 100 == 0:
                print(f"Created {len(pipes)} pipe pairs / {len(pipes) * 2} file descriptors")

        except OSError as e:
            if e.errno == errno.EMFILE:
                print("Hit per-process limit: Too many open files")
                print(f"Created {len(pipes)} pipe pairs / {len(pipes) * 2} file descriptors")
                break
            elif e.errno == errno.ENFILE:
                print("Hit system-wide limit: Too many open files in system")
                print(f"Created {len(pipes)} pipe pairs / {len(pipes) * 2} file descriptors")
                break
            else:
                raise

    input("Press Enter to close all file descriptors and exit...")

finally:
    for read_fd, write_fd in pipes:
        try:
            os.close(read_fd)
            os.close(write_fd)
        except OSError:
            pass
```

This keeps every pipe pair open in `pipes` until `os.pipe()` fails with `EMFILE` / “Too many open files”, then cleans them up when you press Enter.
